 const intro32=document.createElement('p');intro32.innerHTML='Se analiza la precipitaci&oacute;n mensual IMERG promediada sobre el pol&iacute;gono de la cuenca. Referencia fija: '+d32.reference_period+'; '+d32.valid_months+' meses consecutivos, sin faltantes. Para cada mes calendario se calculan media y desviaci&oacute;n est&aacute;ndar muestral (n&minus;1), usando '+d32.months[0].n+' a&ntilde;os v&aacute;lidos por mes.';s32.appendChild(intro32);
 const table32=document.createElement('table');table32.className='tabla-climatologia';table32.innerHTML='<thead><tr><th>Mes</th><th>Media (mm/mes)</th><th>Desv. est&aacute;ndar (mm/mes)</th><th>A&ntilde;os</th></tr></thead><tbody>'+d32.months.map(x=>'<tr><td>'+x.month+'</td><td>'+x.mean.toFixed(2)+'</td><td>'+x.sd.toFixed(2)+'</td><td>'+x.n+'</td></tr>').join('')+'</tbody>';s32.appendChild(table32);
 function plot32(id,title,values,ytitle){const box=document.createElement('div');box.className='panel';box.id=id;const head=document.createElement('h4');head.textContent=title;box.appendChild(head);const plot=document.createElement('div');plot.style.height='350px';box.appendChild(plot);s32.appendChild(box);if(window.Plotly)Plotly.newPlot(plot,[{x:d32.dates,y:values,type:'scatter',mode:'lines',line:{color:'#137c8b',width:1.5},hovertemplate:'%{x}<br>%{y:.2f}<extra></extra>'}],{margin:{l:65,r:25,t:20,b:55},xaxis:{title:'Mes'},yaxis:{title:ytitle},paper_bgcolor:'white',plot_bgcolor:'white'}, {responsive:true,displaylogo:false});else plot.textContent='La gr&aacute;fica requiere conexi&oacute;n a Plotly.';}
