const s42=sub(p4,'guia-4-2','4.2. Construir e interpretar los espectros');
function card42(title,html){const a=document.createElement('article');a.className='tarjeta-fourier';a.innerHTML='<h4>'+title+'</h4>'+html;s42.appendChild(a);return a;}
card42('Cómo leer las curvas','<p>Espectros unilaterales de potencia normalizada: cada bin muestra su porcentaje de la varianza de esa serie (100% al sumar las frecuencias positivas). Esta escala compara la forma del espectro, no la variabilidad absoluta entre variables. Frecuencia en ciclos/mes y eje superior con el periodo equivalente en meses. Las curvas corresponden a originales centradas y anomalías mensuales con referencia fija 1998–2022.</p><p><b>No se hicieron pruebas de significancia de los picos:</b> los máximos son descriptivos y no prueban periodicidad ni causa climática.</p>');
const titles={CHIRPS:'CHIRPS · precipitación de referencia',IMERG:'IMERG · precipitación sobre el polígono',Q:'Caudal observado · Cartago',T:'Temperatura media · ERA5-Land'};
for(const sample of ['full','common']){
 const meta=d42.windows[sample];
 const panel=document.createElement('article');panel.className='tarjeta-fourier';
 panel.innerHTML='<h4>'+(sample==='full'?'Tramos continuos individuales':'Misma ventana para las cuatro series')+'</h4><p>'+(sample==='full'?'CHIRPS y Q: '+meta.CHIRPS.start+' a '+meta.CHIRPS.end+' (N='+meta.CHIRPS.n+'); IMERG: '+meta.IMERG.start+' a '+meta.IMERG.end+' (N='+meta.IMERG.n+'); ERA5-Land: '+meta.T.start+' a '+meta.T.end+' (N='+meta.T.n+'). La resolución de frecuencia cambia con N.':'Enero de 1998 a enero de 2004; N=73 y Δf=0,01370 ciclos/mes para todas las series largas. El segmento común está limitado por vacíos fuera de esta ventana.')+'</p>';
 const grid=document.createElement('div');grid.className='fourier-grid';panel.appendChild(grid);s42.appendChild(panel);
 for(const key of ['CHIRPS','IMERG','Q','T']){
  const box=document.createElement('div');box.className='grafica-fourier';const plot=document.createElement('div');box.appendChild(plot);grid.appendChild(box);
  const entry=d42.spectra[sample][key], n=meta[key].n;
  const traces=[['original','Original centrada','#174f68'],['anomaly','Anomalía mensual','#d27a32']].map(([rep,name,color])=>({x:entry[rep].frequency,y:entry[rep].share_pct,type:'scatter',mode:'lines',name,line:{color,width:1.6},hovertemplate:'%{x:.4f} ciclos/mes<br>%{y:.2f}% de varianza<extra>'+name+'</extra>'}));
  const periodTicks=[2,6,12,24,60,120].filter(x=>x<=n);const freqTicks=periodTicks.map(x=>1/x);
  const layout={height:330,margin:{l:64,r:20,t:62,b:52},title:{text:titles[key]+' · N='+n,font:{size:14}},xaxis:{type:'log',title:'Frecuencia (ciclos/mes)',range:[Math.log10(1/n),Math.log10(.5)],tickvals:[1/n,1/12,1/6,.5],tickformat:'.3f',gridcolor:'#e6ecef'},xaxis2:{type:'log',overlaying:'x',side:'top',title:'Periodo equivalente (meses)',range:[Math.log10(1/n),Math.log10(.5)],tickvals:freqTicks,ticktext:periodTicks.map(String)},yaxis:{title:'Varianza espectral por bin (%)',rangemode:'tozero',gridcolor:'#e6ecef'},paper_bgcolor:'#fff',plot_bgcolor:'#fff',legend:{orientation:'h',y:-.24},shapes:[{type:'line',xref:'x',yref:'paper',x0:1/12,x1:1/12,y0:0,y1:1,line:{color:'#777',dash:'dot',width:1}},{type:'line',xref:'x',yref:'paper',x0:1/6,x1:1/6,y0:0,y1:1,line:{color:'#999',dash:'dash',width:1}}]};
  if(window.Plotly)Plotly.newPlot(plot,traces,layout,{responsive:true,displaylogo:false});
 }
}
const fmt=x=>x.period_months==null?'—':x.period_months+' meses; '+x.cycles_observed.toFixed(1)+' ciclos; '+x.band_share_pct.toFixed(1)+'%';
const table=document.createElement('table');table.className='tabla-fourier';
table.innerHTML='<thead><tr><th>Variable</th><th>Muestra (N; Δf)</th><th>Transformación</th><th>Banda anual (10–14 meses)</th><th>Banda semianual (5–7 meses)</th><th>Interanual (24–120 meses)</th></tr></thead><tbody>'+d42.rows.map(r=>'<tr><td>'+r.variable+'</td><td>'+r.period+'; N='+r.n+'; '+r.df.toFixed(5)+'</td><td>'+r.transformation+'</td><td>'+fmt(r.annual)+'</td><td>'+fmt(r.semiannual)+'</td><td>'+fmt(r.interannual_2_10y)+'</td></tr>').join('')+'</tbody>';
card42('Picos por banda, resolución y ciclos observados','<p>En cada banda se muestra el máximo local: periodo aproximado; número de ciclos observados en el tramo; porcentaje de varianza total de la serie contenido en esa banda. El periodo interanual se limita a N meses y un pico en N representa un solo ciclo, no una periodicidad repetida.</p>');s42.appendChild(table);
const shares=d42.common_band_shares;
card42('Climatología y respuesta hidrológica','<p>En el periodo común, la banda semianual representa '+shares.CHIRPS.original_short_lt6_pct+'% de la potencia de CHIRPS y '+shares.IMERG.original_short_lt6_pct+'% de IMERG para periodos menores de seis meses; sus picos semianuales se atenúan mucho al restar la climatología mensual. Q y temperatura concentran una proporción mayor en bandas de 24 meses o más, mientras lluvia conserva más variabilidad rápida. El patrón es compatible con almacenamiento y tránsito que integran parte de las fluctuaciones rápidas de la lluvia. Son porcentajes normalizados por serie; los espectros no contienen fase y no permiten inferir desfases ni causalidad.</p><p>Los picos anuales y semianuales son coherentes con el ciclo estacional de la cuenca. La ventana común de 73 meses contiene apenas seis ciclos anuales: su máximo de baja frecuencia equivale a una oscilación a lo largo de toda la muestra. No basta para atribuirlo a ENSO u otro modo climático.</p>');
const station=document.createElement('article');station.className='nota-fourier alerta-fourier';station.innerHTML='<b>Precipitación local Zaragoza-AUT:</b> el periodo disponible termina en '+d42.station.last+'; de '+d42.station.available_months+' meses solo '+d42.station.complete_months+' tienen cobertura completa y el tramo continuo máximo dura '+d42.station.longest_full_run.n+' meses. No permite resolver el ciclo anual. Se necesita ampliar el registro antes de producir un espectro interpretable. CHIRPS se usa como precipitación de referencia, no como observación local.';s42.appendChild(station);
const details=document.createElement('details');details.className='fourier-details';details.innerHTML='<summary>Sensibilidad a ventana, tendencia, extremos y periodo</summary><p>Se compararon ventana rectangular y Hann, anomalías sin y con detrendado lineal, winsorización P5–P95 y los tramos individuales frente a la ventana común.</p>';
const stab=document.createElement('table');stab.className='tabla-fourier';stab.innerHTML='<thead><tr><th>Muestra</th><th>Variable</th><th>Variante</th><th>Pico global aproximado</th><th>Anual</th><th>Semianual</th><th>Interanual</th></tr></thead><tbody>'+d42.sensitivity.map(r=>'<tr><td>'+r.sample+'</td><td>'+r.variable+'</td><td>'+r.variant+'</td><td>'+r.dominant_period_months+' meses</td><td>'+((r.annual_peak_months||'—')+' meses')+'</td><td>'+((r.semiannual_peak_months||'—')+' meses')+'</td><td>'+((r.interannual_peak_months||'—')+' meses')+'</td></tr>').join('')+'</tbody>';details.appendChild(stab);s42.appendChild(details);

